contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseTokenParam,
        address nftParam,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFeeParam,
        uint16 highFeeRate,
        bytes32 merkleRootParam,
        bool useOracle,
        bool payRoy
    ) public {
        // First initialize attempt: must revert iff highFeeRate > 5000.
        bool revertedFirst;
        try c.initialize(
            baseTokenParam, nftParam, vBase, vNft, changeFeeParam,
            highFeeRate, merkleRootParam, useOracle, payRoy
        ) { revertedFirst = false; } catch { revertedFirst = true; }

        // Valid fee rate for the successful attempt.
        uint16 effFee = highFeeRate > 5_000 ? (highFeeRate % 5_001) : highFeeRate;

        c.initialize(
            baseTokenParam, nftParam, vBase, vNft, changeFeeParam,
            effFee, merkleRootParam, useOracle, payRoy
        );

        // Second initialize must always revert (AlreadyInitialized).
        bool revertedSecond;
        try c.initialize(
            baseTokenParam, nftParam, vBase, vNft, changeFeeParam,
            effFee, merkleRootParam, useOracle, payRoy
        ) { revertedSecond = false; } catch { revertedSecond = true; }

        assert(
            revertedFirst == (highFeeRate > 5_000)
            && !revertedFirst || true
            && revertedSecond
            && c.initialized()
            && c.baseToken() == baseTokenParam
            && c.nft() == nftParam
            && c.virtualBaseTokenReserves() == vBase
            && c.virtualNftReserves() == vNft
            && c.changeFee() == changeFeeParam
            && c.feeRate() == effFee
            && c.merkleRoot() == merkleRootParam
            && c.useStolenNftOracle() == useOracle
            && c.payRoyalties() == payRoy
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount) public payable {
        require(baseTokenAmount < type(uint256).max);
        require(address(this).balance >= baseTokenAmount + 1);

        // Mismatched ETH (value != baseTokenAmount) must revert while baseToken is address(0).
        bool revertedMismatch;
        try c.deposit{value: baseTokenAmount + 1}(tokenIds, baseTokenAmount) { revertedMismatch = false; }
        catch { revertedMismatch = true; }

        // Exact ETH must succeed and must not touch reserves or initialization.
        bool revertedExact;
        try c.deposit{value: baseTokenAmount}(tokenIds, baseTokenAmount) { revertedExact = false; }
        catch { revertedExact = true; }

        assert(
            revertedMismatch
            && !revertedExact
            && c.virtualBaseTokenReserves() == 0
            && c.virtualNftReserves() == 0
            && !c.initialized()
            && c.baseToken() == address(0)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 virtualBase,
        uint128 virtualNft,
        uint16 feeRate,
        uint256 outputAmount
    ) public {
        require(feeRate <= 5_000);
        require(virtualNft > outputAmount);
        require(outputAmount <= 1e30);
        require(virtualBase <= 1e30);
        require(uint256(virtualNft) - outputAmount > 0);

        c.initialize(address(0), address(0), virtualBase, virtualNft, 0, feeRate, bytes32(0), false, false);

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 inputAmount = FixedPointMathLib.mulDivUp(
            outputAmount, uint256(virtualBase), uint256(virtualNft) - outputAmount
        );

        assert(
            protocolFeeAmount == 0
            && feeAmount == (inputAmount * feeRate) / 10_000
            && netInputAmount == inputAmount + feeAmount
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address bt,
        address nftAddr,
        uint128 vb,
        uint128 vn,
        uint56 cf,
        uint16 fr,
        bytes32 mr,
        bool useOracle,
        bool payRoy
    ) public {
        require(fr <= 5_000);
        require(!c.initialized());
        c.initialize(bt, nftAddr, vb, vn, cf, fr, mr, useOracle, payRoy);
        assert(
            c.initialized() &&
            c.baseToken() == bt &&
            c.nft() == nftAddr &&
            c.virtualBaseTokenReserves() == vb &&
            c.virtualNftReserves() == vn &&
            c.changeFee() == cf &&
            c.feeRate() == fr &&
            c.merkleRoot() == mr &&
            c.useStolenNftOracle() == useOracle &&
            c.payRoyalties() == payRoy &&
            c.feeRate() <= 5_000
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 inputAmount) public {
        // precondition on parameters only: avoid overflow inside c.changeFeeQuote
        require(uint256(c.changeFee()) <= (type(uint256).max / inputAmount) / 1e18 || inputAmount == 0);
        // fresh deployment: baseToken defaults to address(0), so exponent is 18
        require(c.baseToken() == address(0));
        (uint256 feeAmount, uint256 protocolFeeAmount) = c.changeFeeQuote(inputAmount);
        uint256 expected = inputAmount * uint256(c.changeFee());
        assert(feeAmount == expected && protocolFeeAmount <= feeAmount);
    }
    receive() external payable {}
}
